// Words splits text on whitespace.
func Words(s string) []string {
	return strings.Fields(s)
}

// Wrap wraps text into lines of at most width characters, breaking only at spaces.
// A word longer than width goes on a line of its own. Runs of whitespace collapse;
// no line begins or ends with a space. Empty input returns an empty slice.
// A width of zero or less returns nil.
func Wrap(text string, width int) []string {
	if width <= 0 {
		return nil
	}

	fields := strings.Fields(text)
	if len(fields) == 0 {
		return nil
	}

	lines := []string{}
	var current strings.Builder

	for _, word := range fields {
		if current.Len() == 0 {
			current.WriteString(word)
		} else if current.Len()+1+len(word) <= width {
			current.WriteByte(' ')
			current.WriteString(word)
		} else {
			lines = append(lines, current.String())
			current.Reset()
			current.WriteString(word)
		}
	}

	if current.Len() > 0 {
		lines = append(lines, current.String())
	}

	return lines
}

