package text

import "testing"

func TestWords(t *testing.T) {
	if len(Words("a b  c")) != 3 {
		t.Fatal("expected three words")
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name   string
		text   string
		width  int
		want   []string
	}{
		{
			name:  "simple wrap",
			text:  "hello world foo bar",
			width: 10,
			want:   []string{"hello", "world foo"},
		},
		{
			name:  "no wrapping needed",
			text:  "hello world",
			width: 20,
			want:   []string{"hello world"},
		},
		{
			name:  "word longer than width",
			text:  "superlongword short",
			width: 5,
			want:   []string{"superlongword", "short"},
		},
		{
			name:  "empty input",
			text:  "",
			width: 10,
			want:   nil,
		},
		{
			name:  "whitespace-only input",
			text:  "   ",
			width: 10,
			want:   nil,
		},
		{
			name:  "zero width",
			text:  "hello world",
			width: 0,
			want:   nil,
		},
		{
			name:  "negative width",
			text:  "hello world",
			width: -1,
			want:   nil,
		},
		{
			name:  "multiple spaces collapse",
			text:  "a   b    c",
			width: 10,
			want:   []string{"a b c"},
		},
		{
			name:  "leading and trailing whitespace",
			text:  "  hello world  ",
			width: 10,
			want:   []string{"hello", "world"},
		},
		{
			name:  "single word fits",
			text:  "hello",
			width: 10,
			want:   []string{"hello"},
		},
		{
			name:  "single word too long",
			text:  "supercalifragilistic",
			width: 5,
			want:   []string{"supercalifragilistic"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := Wrap(tt.text, tt.width)
			if len(got) == 0 && got == nil && tt.want != nil {
				t.Fatalf("got empty slice, want %v", tt.want)
			}
			if len(got) != len(tt.want) {
				t.Fatalf("got %d lines, want %d: got=%q, want=%q", len(got), len(tt.want), got, tt.want)
			}
			for i, line := range got {
				if line != tt.want[i] {
					t.Errorf("line %d: got %q, want %q", i, line, tt.want[i])
				}
			}
		})
	}
}

